INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1000001, 190801, 13, 1000, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "様々なミニゲームをご用意してい\nますよ！\nどのミニゲームで遊びますか？");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1000002, 190801, 13, 1000, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "楽しいミニゲームをご紹介！\nあなたはどのミニゲームで\n遊びますか？");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1001001, 190801, 13, 1001, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "こちらは{0}ルピで\n販売中！\nぜひ購入して\n遊んでくださいね！");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1002001, 190801, 12, 1002, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "動くハートに合わせてタップ！\nシズルさんとエリコさんの\nチョコレートケーキ作りを\nお手伝いしましょう！");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1003001, 190801, 11, 1003, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "クウカさんを引っ張ってより遠く\nへ飛ばしてあげましょう！\n色々なハプニングでクウカさんに\nエクスタシーを届けましょう！");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1004001, 190801, 3, 1004, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "左右をタップしてマジムンを倒し\nましょう！\n放て！\n琉球犬アラウンドシュート！");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1005001, 190801, 7, 1005, "2030-04-01 14:00:00", 0, "2020-02-15 15:00:00", "パネルをタップしてドラゴンズ\nネストのみなさんと一緒に\nしりとり対決をしませんか？\nおしりに「ん」はご法度です。");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1006001, 190801, 2, 1006, "2030-04-01 14:00:00", 0, "2020-05-31 12:00:00", "素早い動きのネズミに合わせ、\nタップで撃退！\nやる気のリンさんと一緒に\n大切なチーズを守りましょう！");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1007001, 190801, 4, 1007, "2030-04-01 14:00:00", 0, "2020-08-15 15:00:00", "ミサトさんや部員のみなさんと\nバッティングの特訓ですよ！\nホームランを目指して、ボールを\nタイミングよく打ち返しましょう");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1008001, 190801, 6, 1008, "2030-04-01 14:00:00", 0, "2021-08-31 12:00:00", "カルミナメダルを使って、\n応援グッズをゲットしましょう！\nメダルはルピを使って\n交換できますよ。\n");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1009001, 190801, 13, 1009, "2030-04-01 14:00:00", 0, "2021-12-18 15:00:00", "食べたプリンはプリンノート\nで確認してみましょう！\nプリンの材料はルピを使って\n購入できますよ。");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1010001, 190801, 4, 1010, "2030-04-01 14:00:00", 0, "2022-02-15 15:00:00", "チームでクイズに挑みましょう！\nソロで自分の実力を試すか、マル\nチで仲間と一緒に遊ぶか、好きな\nモードを選んでくださいね♪");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1011001, 190801, 6, 1011, "2030-04-01 14:00:00", 0, "2022-07-18 15:00:00", "３つのラウンドを駆け抜け、\n総合１位を目指しましょう！\n参加者の皆さんの特徴や、\nＧＰの特徴にも注目です♪");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1012001, 190801, 6, 1012, "2030-04-01 14:00:00", 0, "2023-09-18 15:00:00", "キャルさん、スズナさんと一緒に\nクイズでお勉強しましょう！\n放課後の教室で二人きりって…\nなんだかドキドキしますね♪");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1013001, 190801, 6, 1013, "2030-04-01 14:00:00", 0, "2024-04-18 15:00:00", "魔物の討伐任務にいざ行軍！\nエリコさん、マコトさんの\n頼もしい背中は、\n新兵さんたちの憧れですね♪");
INSERT INTO `v1_3e4b82e0ab82523696a0d67bdfd1e634453b867368eece2a9d270604b961e0e9` VALUES (1014001, 190801, 6, 1014, "2030-04-01 14:00:00", 0, "2024-11-18 15:00:00", "バンディ・シスターズのみなさん\nと戦車バトルに挑戦です！\nパーツやメンバーの組み合わせで\nマシンの特徴が変化しますよ♪");
